// Extrae hasta 5 titulares de tendencia para pasar como contexto al generador.
const results = Array.isArray(items[0].json?.results) ? items[0].json.results : [];
const trends = results.slice(0, 5).map(r => (r.title || '').trim()).filter(Boolean);
return [{ json: { trends } }];

// Arma el mensaje de Telegram con los 3 guiones para aprobacion.
const payload = items[0].json || {};
const scripts = Array.isArray(payload.scripts) ? payload.scripts : (Array.isArray(payload.data?.scripts) ? payload.data.scripts : []);
const date = payload.date || new Date().toISOString().slice(0,10);
const lines = [`ONIA | Guiones de contenido ${date}`, ''];
if (scripts.length === 0) {
  lines.push('No llegaron guiones. Revisar endpoint /content/daily-scripts en ONIA Center o correr la skill guiones-diarios-onia a mano.');
} else {
  scripts.slice(0,3).forEach((s, i) => {
    lines.push(`GUION ${i+1} — ${s.pilar || ''} — ${s.formato || ''}`);
    if (s.gancho) lines.push(`Gancho: ${s.gancho}`);
    if (s.cta) lines.push(`CTA: ${s.cta}`);
    lines.push('');
  });
  lines.push('Para producir: "Genera Reel ONIA: <tema>" o "Flujo carrusel: <slug>". Nada se publica sin tu OK.');
}
return [{ json: { text: lines.join('\n').slice(0, 3900), scripts } }];
